func (informationLeakageCodec) buildConfigsPatch(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (wafmodule.Patch, diag.Diagnostics) {
	if configured.IsNull() {
		return informationLeakagePatch{}, diagnostics
	}
	if configured.IsUnknown() || planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown information leakage configuration", "The configs block must be known during apply.")
		return nil, diagnostics
	}

	var configValues, planValues informationLeakageConfigsModel
	diagnostics.Append(configured.As(ctx, &configValues, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planValues, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}

	patch := informationLeakagePatch{}
	patch.Action, diagnostics = informationLeakageConfiguredString(configValues.Action, planValues.Action, "action", diagnostics)
	if patch.Action.Set && !informationLeakageConfigActionValid(patch.Action.Value) {
		diagnostics.AddError("Invalid information leakage action", "action must be one of alert, alert_erase, deny_erase_no_log.")
	}
	patch.CloakErrorPages, diagnostics = informationLeakageConfiguredBool(configValues.CloakErrorPages, planValues.CloakErrorPages, "cloak_error_pages", diagnostics)
	patch.EraseHttpHeaders, diagnostics = informationLeakageConfiguredBool(configValues.EraseHttpHeaders, planValues.EraseHttpHeaders, "erase_http_headers", diagnostics)
	patch.PersonalInfo, diagnostics = informationLeakageConfiguredBool(configValues.PersonalInfo, planValues.PersonalInfo, "personal_info", diagnostics)
	patch.ServerInfoDisclose, diagnostics = informationLeakageConfiguredBool(configValues.ServerInfoDisclose, planValues.ServerInfoDisclose, "server_info_disclose", diagnostics)
	patch.Status, diagnostics = informationLeakageConfiguredBool(configValues.Status, planValues.Status, "status", diagnostics)

	patch.SigExceptRules, diagnostics = informationLeakageBuildConfiguredSigExceptRules(ctx, configValues.SigExceptRules, planValues.SigExceptRules, diagnostics)
	patch.HttpHeaders, diagnostics = informationLeakageBuildConfiguredHttpHeaders(ctx, configValues.HttpHeaders, planValues.HttpHeaders, diagnostics)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return patch, diagnostics
}

