func (informationLeakageCodec) Flatten(ctx context.Context, epID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	model := informationLeakageResourceModel{
		EPID:     types.StringValue(epID),
		Template: types.BoolValue(result.Template),
		Configs:  types.ObjectNull(informationLeakageConfigAttributeTypes),
	}
	scalars, diagnostics := informationLeakageDecodeScalars(result)
	if diagnostics.HasError() || result.Template {
		return &model, diagnostics
	}
	owned, ownershipDiagnostics := informationLeakageOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	scalarValues := map[string]attr.Value{}
	scalarValues["action"] = types.StringValue(scalars.Action)
	cloak_error_pagesScalar := types.BoolNull()
	if scalars.CloakErrorPages != nil {
		cloak_error_pagesScalar = types.BoolValue(*scalars.CloakErrorPages)
	}
	scalarValues["cloak_error_pages"] = cloak_error_pagesScalar
	erase_http_headersScalar := types.BoolNull()
	if scalars.EraseHttpHeaders != nil {
		erase_http_headersScalar = types.BoolValue(*scalars.EraseHttpHeaders)
	}
	scalarValues["erase_http_headers"] = erase_http_headersScalar
	personal_infoScalar := types.BoolNull()
	if scalars.PersonalInfo != nil {
		personal_infoScalar = types.BoolValue(*scalars.PersonalInfo)
	}
	scalarValues["personal_info"] = personal_infoScalar
	server_info_discloseScalar := types.BoolNull()
	if scalars.ServerInfoDisclose != nil {
		server_info_discloseScalar = types.BoolValue(*scalars.ServerInfoDisclose)
	}
	scalarValues["server_info_disclose"] = server_info_discloseScalar
	scalarValues["status"] = types.BoolValue(scalars.Status)

	sigExceptRulesList := types.ObjectNull(informationLeakageSigExceptRulesWrapperAttributeTypes)
	if owned.SigExceptRules {
		items, itemDiagnostics := informationLeakageDecodeSigExceptRules(result.Configs["sig_except_rules"])
		diagnostics.Append(itemDiagnostics...)
		subItemOwnedMasks := make(map[string][]bool)
		// Decode nested sub-item arrays for owned items only (fail-closed on
		// unknown keys). Unowned items leave the nested array nil (opaque).
		// Decode item-level scalar-string-arrays for owned items only (fail-
		// closed on unknown keys). Unowned items leave the array nil (opaque).
		sigExceptRulesList, itemDiagnostics = informationLeakageSigExceptRulesWrapperValue(items, subItemOwnedMasks)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["sig_except_rules"] = sigExceptRulesList
	httpHeadersList := types.ObjectNull(httpHeadersWrapperAttributeTypes)
	if owned.HttpHeaders {
		items, itemDiagnostics := informationLeakageDecodeHttpHeaders(result.Configs["http_headers"])
		diagnostics.Append(itemDiagnostics...)
		httpHeadersList, itemDiagnostics = informationLeakageHttpHeadersWrapperValue(items)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["http_headers"] = httpHeadersList
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	model.Configs, diagnostics = types.ObjectValue(informationLeakageConfigAttributeTypes, scalarValues)
	return &model, diagnostics
}

func (codec informationLeakageCodec) FlattenTemplate(ctx context.Context, templateID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	result.Template = false
	appModelAny, diagnostics := codec.Flatten(ctx, templateID, result, ownership)
	if diagnostics.HasError() || appModelAny == nil {
		return nil, diagnostics
	}
	appModel, ok := appModelAny.(*informationLeakageResourceModel)
	if !ok {
		diagnostics.AddError("Unable to flatten information leakage template configuration", fmt.Sprintf("Unexpected app model type %T.", appModelAny))
		return nil, diagnostics
	}
	return &wafmodule.TemplateModel{
		TemplateID: types.StringValue(templateID),
		Configs:    appModel.Configs,
	}, diagnostics
}

func (patch informationLeakagePatch) Apply(_ context.Context, result *client.WAFModuleResult) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if result == nil {
		diagnostics.AddError("Unable to merge information leakage configuration", "The current API result was nil.")
		return diagnostics
	}
	set := func(name string, value any) {
		if err := result.SetConfig(name, value); err != nil {
			diagnostics.AddError("Unable to merge information leakage configuration", fmt.Sprintf("Unable to encode %s: %v", name, err))
		}
	}
	if patch.Action.Set {
		set("action", patch.Action.Value)
	}
	if patch.CloakErrorPages.Set {
		set("cloak_error_pages", patch.CloakErrorPages.Value)
	}
	if patch.EraseHttpHeaders.Set {
		set("erase_http_headers", patch.EraseHttpHeaders.Value)
	}
	if patch.PersonalInfo.Set {
		set("personal_info", patch.PersonalInfo.Value)
	}
	if patch.ServerInfoDisclose.Set {
		set("server_info_disclose", patch.ServerInfoDisclose.Value)
	}
	if patch.Status.Set {
		set("status", patch.Status.Value)
	}

	if patch.SigExceptRules.Set {
		set("sig_except_rules", patch.SigExceptRules.Items)
	}
	if patch.HttpHeaders.Set {
		set("http_headers", patch.HttpHeaders.Items)
	}
	return diagnostics
}

func informationLeakageValidateConfiguredSigExceptRules(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value informationLeakageWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > informationLeakageSigExceptRulesMaxItems {
		diagnostics.AddError("Invalid information leakage sig_except_rules", fmt.Sprintf("sig_except_rules may contain at most %d item blocks.", informationLeakageSigExceptRulesMaxItems))
		return diagnostics
	}
	var items []informationLeakageSigExceptRulesItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("sig_except_rules item %d", index+1)
		if item.Cookie.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" cookie is required.")
		} else if !item.Cookie.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedCookie(ctx, location, item.Cookie)...)
		}
		if item.Host.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" host is required.")
		} else if !item.Host.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedHost(ctx, location, item.Host)...)
		}
		if item.HttpHeader.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" http_header is required.")
		} else if !item.HttpHeader.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedHttpHeader(ctx, location, item.HttpHeader)...)
		}
		if item.Json.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" json is required.")
		} else if !item.Json.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedJson(ctx, location, item.Json)...)
		}
		if item.Param.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" param is required.")
		} else if !item.Param.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedParam(ctx, location, item.Param)...)
		}
		if item.SigID.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" sig_id is required.")
		} else if !item.SigID.IsUnknown() {
			informationLeakageValidateString(location, " sig_id", item.SigID.ValueString(), 9, 9, &diagnostics)
		}
		if item.SigName.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" sig_name is required.")
		} else if !item.SigName.IsUnknown() {
			informationLeakageValidateString(location, " sig_name", item.SigName.ValueString(), 0, 0, &diagnostics)
		}
		if item.URL.IsNull() {
			diagnostics.AddError("Invalid information leakage item", location+" url is required.")
		} else if !item.URL.IsUnknown() {
			diagnostics.Append(informationLeakageSigExceptRulesValidateNestedURL(ctx, location, item.URL)...)
		}
	}
	return diagnostics
}
