func informationLeakageOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (informationLeakageOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return informationLeakageOwnershipSet{SigExceptRules: false, HttpHeaders: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return informationLeakageOwnershipSet{SigExceptRules: true, HttpHeaders: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return informationLeakageOwnershipSet{SigExceptRules: false, HttpHeaders: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown information leakage ownership", "The configs ownership state was unknown while flattening.")
		return informationLeakageOwnershipSet{SigExceptRules: false, HttpHeaders: false}, diagnostics
	}
	var configs informationLeakageConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return informationLeakageOwnershipSet{SigExceptRules: !configs.SigExceptRules.IsNull(), HttpHeaders: !configs.HttpHeaders.IsNull()}, diagnostics
}
