func informationLeakageValidateConfiguredHttpHeaders(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var model struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(wrapper.As(ctx, &model, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || model.Items.IsNull() || model.Items.IsUnknown() {
		return diagnostics
	}
	if len(model.Items.Elements()) > informationLeakageHttpHeadersMaxItems {
		diagnostics.AddError("Invalid information leakage http_headers", fmt.Sprintf("http_headers may contain at most %d item blocks.", informationLeakageHttpHeadersMaxItems))
		return diagnostics
	}
	var items []httpHeadersItemModel
	diagnostics.Append(model.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("http_headers item %d", index+1)
		if item.Header.IsNull() {
			diagnostics.AddError("Invalid information leakage http_headers", location+" header is required.")
		}
	}
	return diagnostics
}

func informationLeakageBuildConfiguredHttpHeaders(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (httpHeadersOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return httpHeadersOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown information leakage http_headers", "The http_headers ownership wrapper must be known during apply.")
		return httpHeadersOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown information leakage http_headers", "The planned http_headers ownership wrapper must be known during apply.")
		return httpHeadersOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return httpHeadersOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown information leakage http_headers", "The http_headers item blocks must be known during apply.")
		return httpHeadersOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return httpHeadersOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	var configItems, planItems []httpHeadersItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid information leakage http_headers", "The planned item list unexpectedly became null.")
		}
		return httpHeadersOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return httpHeadersOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid information leakage http_headers", "Configured and planned item counts differ.")
		return httpHeadersOwnedList{}, diagnostics
	}
	if len(configItems) > informationLeakageHttpHeadersMaxItems {
		diagnostics.AddError("Invalid information leakage http_headers", fmt.Sprintf("http_headers may contain at most %d item blocks.", informationLeakageHttpHeadersMaxItems))
		return httpHeadersOwnedList{}, diagnostics
	}
	items := make([]string, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("http_headers item %d", index+1)
		if configuredItem.Header.IsNull() {
			diagnostics.AddError("Invalid information leakage http_headers", "The required "+location+" header is null.")
			continue
		}
		value := ""
		if configuredItem.Header.IsUnknown() {
			if plannedItem.Header.IsNull() || plannedItem.Header.IsUnknown() {
				diagnostics.AddError("Unknown information leakage http_headers", "The configured "+location+" header is still unknown during apply.")
				continue
			}
			value = plannedItem.Header.ValueString()
		} else {
			value = configuredItem.Header.ValueString()
		}
		items = append(items, value)
	}
	return httpHeadersOwnedList{Set: true, Items: items}, diagnostics
}

